/**
 * SearchModal — 全局搜索模态框
 *
 * 支持 Ctrl+K / Cmd+K 快捷键打开。
 * 搜索范围：配方、实验、原料。
 * 调用 GET /api/v1/search/global（真实端点，跨类型模糊搜索）。
 *
 * 此前指向 /api/v1/ai/search —— 该路由后端不存在，fetch 返回 404 后被
 * catch 成空结果，用户看到的是"未找到匹配结果"，误以为搜索功能正常但库里
 * 没有数据；实际是搜索根本没执行。
 */
import { useState, useCallback, useRef, useEffect } from 'react';
import { Search, X } from 'lucide-react';
import type { SearchResult } from '@/types/ai.api';

interface SearchModalProps {
  isOpen: boolean;
  onClose: () => void;
}

/** 后端 /search/global 返回 items[].description，前端类型字段叫 snippet */
function normalizeSearchItems(data: unknown): SearchResult[] {
  const payload = data as { types?: Record<string, { items?: unknown[] }> };
  const out: SearchResult[] = [];
  const seen = new Set<string>();
  for (const bucket of Object.values(payload?.types ?? {})) {
    for (const raw of (bucket?.items ?? []) as Array<Record<string, unknown>>) {
      const id = String(raw.id ?? '');
      if (!id || seen.has(id)) continue;
      seen.add(id);
      const type = String(raw.type ?? '') as SearchResult['type'];
      out.push({
        id,
        type: type === 'formula' || type === 'ingredient' || type === 'experiment' ? type : 'analysis',
        title: String(raw.title ?? ''),
        snippet: String(raw.description ?? ''),
        score: typeof raw.score === 'number' ? raw.score : 0,
      });
    }
  }
  return out.sort((a, b) => b.score - a.score);
}

export function SearchModal({ isOpen, onClose }: SearchModalProps) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isOpen]);

  // 防抖搜索
  useEffect(() => {
    if (!query.trim()) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setResults([]);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSearchError(null);
      return;
    }
    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        const url = `/api/v1/search/global?q=${encodeURIComponent(query)}&types=formula,experiment,ingredient&page_size=20`;
        const response = await fetch(url);
        if (response.ok) {
          const data = await response.json();
          setResults(normalizeSearchItems(data));
        }
        // 非 200（鉴权/服务异常）不再静默降级成"无结果"，明确标记失败
        else {
          setResults([]);
          setSearchError(`搜索服务异常（HTTP ${response.status}）`);
        }
      } catch (_error) {
        setResults([]);
        setSearchError('搜索服务不可达');
      } finally {
        setIsSearching(false);
      }
    }, 300);
    return () => clearTimeout(timer);
  }, [query]);

  const handleClose = useCallback(() => {
    setQuery('');
    setResults([]);
    onClose();
  }, [onClose]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 z-[500] flex items-start justify-center pt-24 px-4"
      role="dialog"
      aria-modal="true"
      aria-label="全局搜索"
    >
      {/* 背景遮罩 */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm"  role="button" tabIndex={0} onClick={handleClose} />

      {/* 搜索框 */}
      <div className="relative w-full max-w-2xl bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] shadow-2xl border border-[var(--border-color)] overflow-hidden">
        {/* 输入区 */}
        <div className="flex items-center px-[var(--space-apple-md)] py-[var(--space-apple-sm)] border-b border-[var(--border-color)]">
          <Search className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex-shrink-0" />
          <input
            ref={inputRef}
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="搜索配方、药材、分析工具..."
            className="flex-1 ml-3 bg-transparent text-base focus:outline-none text-neutral-900 dark:text-white placeholder:text-[color:var(--text-muted)] dark:placeholder:text-[color:var(--text-secondary)]"
            aria-label="搜索内容"
          />
          <button
            onClick={handleClose}
            className="ml-2 p-1 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]"
            aria-label="关闭搜索"
          >
            <X className="w-4 h-4" />
          </button>
          <kbd className="ml-3 px-2 py-1 text-xs font-mono text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] bg-neutral-100 dark:bg-neutral-700 rounded">
            ESC
          </kbd>
        </div>

        {/* 结果区 */}
        <div className="max-h-96 overflow-y-auto p-2">
          {isSearching ? (
            <div className="px-4 py-8 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">搜索中...</div>
          ) : results.length > 0 ? (
            <div className="space-y-1">
              {results.map((r) => (
                <button
                  key={r.id}
                  className="w-full text-left px-4 py-3 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-700/50 transition-colors"
                  onClick={handleClose}
                >
                  <div className="flex items-center gap-3">
                    <span
                      className={`w-2 h-2 rounded-full ${
                        r.type === 'formula'
                          ? 'bg-secondary-500'
                          : r.type === 'ingredient'
                            ? 'bg-primary-500'
                            : 'bg-accent-500'
                      }`}
                    />
                    <div>
                      <div className="text-sm font-medium text-neutral-900 dark:text-white">{r.title}</div>
                      <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] truncate">{r.snippet}</div>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          ) : searchError ? (
            <div className="px-4 py-8 text-center text-sm text-error-500">{searchError}</div>
          ) : query.trim() ? (
            <div className="px-4 py-8 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">未找到匹配 "{query}" 的结果</div>
          ) : (
            <div className="px-4 py-8 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">输入关键词开始搜索</div>
          )}
        </div>
      </div>
    </div>
  );
}

export default SearchModal;

import React, { useState } from 'react';

import { logger } from '@/utils/safeLogger';
import {
  CollaborationPermission,
} from '../../../types/collaboration.types';
import type {
  ShareSettings,
  AccessStatistics,
} from '../../../types/collaboration.types';

interface ShareDialogProps {
  isOpen: boolean;
  reportTitle: string;
  currentShareSettings: ShareSettings;
  accessStats?: AccessStatistics | null;
  onShareSettingsChange: (settings: Partial<ShareSettings>) => void;
  onGenerateLink: () => Promise<string>;
  onAddCollaborator: (email: string, permission: CollaborationPermission) => Promise<boolean>;
  onClose: () => void;
}

const ShareDialog: React.FC<ShareDialogProps> = ({
  isOpen,
  reportTitle,
  currentShareSettings,
  accessStats,
  onShareSettingsChange,
  onGenerateLink,
  onAddCollaborator,
  onClose,
}) => {
  const [activeTab, setActiveTab] = useState<'link' | 'email' | 'embed' | 'stats'>('link');
  const [newCollaboratorEmail, setNewCollaboratorEmail] = useState('');
  const [newCollaboratorPermission, setNewCollaboratorPermission] = useState<CollaborationPermission>(CollaborationPermission.VIEW);
  const [copied, setCopied] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  if (!isOpen) return null;

  const handleCopyLink = async () => {
    if (!currentShareSettings.link) {
      setIsGenerating(true);
      await onGenerateLink();
      setIsGenerating(false);
    }

    if (currentShareSettings.link) {
      try {
        await navigator.clipboard.writeText(currentShareSettings.link);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } catch (err) {
        logger.error('Failed to copy:', err);
      }
    }
  };

  const handleAddCollaborator = async () => {
    if (!newCollaboratorEmail.trim()) return;

    const success = await onAddCollaborator(newCollaboratorEmail, newCollaboratorPermission);
    if (success) {
      setNewCollaboratorEmail('');
    }
  };

  const tabs = [
    { id: 'link' as const, label: '链接分享', icon: '🔗' },
    { id: 'email' as const, label: '邀请协作者', icon: '👥' },
    { id: 'embed' as const, label: '嵌入代码', icon: '📎' },
    { id: 'stats' as const, label: '访问统计', icon: '📊' },
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-2xl w-full max-w-2xl mx-4 max-h-[85vh] overflow-hidden flex flex-col">
        <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-neutral-900">分享报告</h3>
            <p className="mt-0.5 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{reportTitle}</p>
          </div>
          <button
            onClick={onClose}
            className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-600 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="flex border-b border-neutral-200 dark:border-neutral-700 px-6">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                activeTab === tab.id
                  ? 'border-secondary-500 text-secondary-600'
                  : 'border-transparent text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-700'
              }`}
            >
              <span className="mr-1.5">{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {activeTab === 'link' && (
            <div className="space-y-4">
              <div>
                <label className="flex items-center space-x-2 mb-3">
                  <input
                    type="checkbox"
                    checked={currentShareSettings.isPublic}
                    onChange={(e) => onShareSettingsChange({ isPublic: e.target.checked })}
                    className="w-4 h-4 text-secondary-600 rounded focus:ring-secondary-500"
                  />
                  <span className="text-sm font-medium text-neutral-700">公开访问（任何人可查看）</span>
                </label>
              </div>

              <div>
                <label className="block text-sm font-medium text-neutral-700 mb-2">分享链接</label>
                <div className="flex items-center space-x-2">
                  <input
                    type="text"
                    value={currentShareSettings.link || ''}
                    readOnly
                    placeholder="点击生成按钮创建分享链接..."
                    className="flex-1 px-3 py-2 border border-neutral-300 rounded-lg bg-neutral-50 dark:bg-neutral-800 text-sm"
                  />
                  <button
                    onClick={handleCopyLink}
                    disabled={isGenerating}
                    className={`px-4 py-2 text-sm font-medium rounded-lg transition-colors ${
                      copied
                        ? 'bg-success-100 text-success-700'
                        : 'bg-secondary-container text-secondary-main hover:bg-secondary-container'
                    }`}
                  >
                    {copied ? '已复制！' : isGenerating ? '生成中...' : '复制链接'}
                  </button>
                  {!currentShareSettings.link && (
                    <button
                      onClick={() => onGenerateLink()}
                      disabled={isGenerating}
                      className="px-4 py-2 text-sm font-medium text-secondary-600 bg-secondary-50 rounded-lg hover:bg-secondary-100"
                    >
                      生成新链接
                    </button>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-4 border-t border-neutral-100">
                <div>
                  <label className="block text-xs font-medium text-neutral-600 mb-1">访问密码（可选）</label>
                  <input
                    type="password"
                    value={currentShareSettings.password || ''}
                    onChange={(e) => onShareSettingsChange({ password: e.target.value || undefined })}
                    placeholder="设置后需要密码才能访问"
                    className="w-full px-3 py-1.5 text-sm border border-neutral-300 dark:border-neutral-700 rounded-md"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-neutral-600 mb-1">有效期至</label>
                  <input
                    type="datetime-local"
                    value={currentShareSettings.expiresAt?.slice(0, 16) || ''}
                    onChange={(e) => onShareSettingsChange({
                      expiresAt: e.target.value ? new Date(e.target.value).toISOString() : null,
                    })}
                    className="w-full px-3 py-1.5 text-sm border border-neutral-300 dark:border-neutral-700 rounded-md"
        aria-label="有效期至"
      />
                </div>
              </div>

              <div className="space-y-2">
                <label className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={currentShareSettings.allowDownload}
                    onChange={(e) => onShareSettingsChange({ allowDownload: e.target.checked })}
                    className="w-4 h-4 text-secondary-600 rounded"
                  />
                  <span className="text-sm text-neutral-700">允许下载</span>
                </label>
                <label className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={currentShareSettings.allowCopy}
                    onChange={(e) => onShareSettingsChange({ allowCopy: e.target.checked })}
                    className="w-4 h-4 text-secondary-600 rounded"
                  />
                  <span className="text-sm text-neutral-700">允许复制内容</span>
                </label>
                <label className="flex items-center space-x-2">
                  <input
                    type="checkbox"
                    checked={currentShareSettings.allowComment}
                    onChange={(e) => onShareSettingsChange({ allowComment: e.target.checked })}
                    className="w-4 h-4 text-secondary-600 rounded"
                  />
                  <span className="text-sm text-neutral-700">允许评论</span>
                </label>
              </div>
            </div>
          )}

          {activeTab === 'email' && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-neutral-700 mb-2">邀请邮箱</label>
                <div className="flex space-x-2">
                  <input
                    type="email"
                    value={newCollaboratorEmail}
                    onChange={(e) => setNewCollaboratorEmail(e.target.value)}
                    placeholder="colleague@example.com"
                    className="flex-1 px-3 py-2 border border-neutral-300 dark:border-neutral-700 rounded-lg text-sm"
                    onKeyDown={(e) => e.key === 'Enter' && handleAddCollaborator()}
                  />
                  <select
                    value={newCollaboratorPermission}
                    onChange={(e) => setNewCollaboratorPermission(e.target.value as CollaborationPermission)}
                    className="px-3 py-2 border border-neutral-300 dark:border-neutral-700 rounded-lg text-sm"
                  >
                    <option value={CollaborationPermission.VIEW}>可查看</option>
                    <option value={CollaborationPermission.COMMENT}>可评论</option>
                    <option value={CollaborationPermission.EDIT}>可编辑</option>
                  </select>
                  <button
                    onClick={handleAddCollaborator}
                    disabled={!newCollaboratorEmail.trim()}
                    className="px-4 py-2 bg-secondary-container text-secondary-main text-sm font-medium rounded-lg hover:bg-secondary-container disabled:opacity-50"
                  >
                    邀请
                  </button>
                </div>
              </div>

              <div className="bg-neutral-50 dark:bg-neutral-800 rounded-lg p-4">
                <h4 className="text-sm font-medium text-neutral-700 mb-3">权限说明</h4>
                <div className="space-y-2 text-xs text-neutral-600">
                  <div className="flex items-start space-x-2">
                    <span className="font-medium text-neutral-900 w-16">可查看</span>
                    <span>只能阅读报告内容，无法修改或添加评论</span>
                  </div>
                  <div className="flex items-start space-x-2">
                    <span className="font-medium text-neutral-900 w-16">可评论</span>
                    <span>可以查看并添加批注和评论，无法编辑正文</span>
                  </div>
                  <div className="flex items-start space-x-2">
                    <span className="font-medium text-neutral-900 w-16">可编辑</span>
                    <span>可以修改报告内容、添加批注和管理协作者</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'embed' && (
            <div className="space-y-4">
              <p className="text-sm text-neutral-600">
                将以下代码嵌入到您的网站或博客中，即可展示此报告：
              </p>
              <div className="relative">
                <pre className="bg-neutral-900 text-success-400 p-4 rounded-lg text-sm overflow-x-auto">
                  <code>{`<iframe
  src="${window.location.origin}/embed/report/${/* eslint-disable-next-line react-hooks/purity */ Date.now()}"
  width="100%"
  height="800"
  frameborder="0"
  allowfullscreen>
</iframe>`}</code>
                </pre>
                <button
                  onClick={() => navigator.clipboard.writeText('embed-code')}
                  className="absolute top-2 right-2 p-1.5 bg-neutral-700 text-white rounded hover:bg-neutral-600"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                  </svg>
                </button>
              </div>
            </div>
          )}

          {activeTab === 'stats' && accessStats && (
            <div className="space-y-6">
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                <StatCard title="总浏览量" value={accessStats.totalViews} icon="👁️" />
                <StatCard title="独立访客" value={accessStats.uniqueVisitors} icon="👤" />
                <StatCard title="下载次数" value={accessStats.totalDownloads} icon="⬇️" />
                <StatCard title="平均停留" value={`${Math.floor(accessStats.averageTimeOnPage / 60)}分钟`} icon="⏱️" />
              </div>

              <div>
                <h4 className="text-sm font-medium text-neutral-700 mb-3">近7天浏览趋势</h4>
                <div className="flex items-end space-x-2 h-32">
                  {accessStats.viewsByDate.map((item: { date: string; count: number }, i: number) => (
                    <div key={i} className="flex-1 flex flex-col items-center">
                      <div
                        className="w-full bg-secondary-500 rounded-t"
                        style={{ height: `${(item.count / Math.max(...accessStats.viewsByDate.map((d: { date: string; count: number }) => d.count))) * 100}%` }}
                      />
                      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{item.date.slice(5)}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <h4 className="text-sm font-medium text-neutral-700 mb-2">来源分布</h4>
                  <div className="space-y-2">
                    {accessStats.topReferrers.map((source: { source: string; count: number }, i: number) => (
                      <div key={i} className="flex items-center justify-between text-sm">
                        <span className="text-neutral-600">{source.source}</span>
                        <span className="font-medium text-neutral-900">{source.count}</span>
                      </div>
                    ))}
                  </div>
                </div>
                <div>
                  <h4 className="text-sm font-medium text-neutral-700 mb-2">地区分布</h4>
                  <div className="space-y-2">
                    {accessStats.geographicDistribution.map((geo: { country: string; count: number }, i: number) => (
                      <div key={i} className="flex items-center justify-between text-sm">
                        <span className="text-neutral-600">{geo.country}</span>
                        <span className="font-medium text-neutral-900">{geo.count}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ title: string; value: string | number; icon: string }> = ({ title, value, icon }) => (
  <div className="bg-neutral-50 dark:bg-neutral-800 rounded-lg p-4 text-center">
    <div className="text-2xl mb-1">{icon}</div>
    <div className="text-display font-semibold text-neutral-900">{value.toLocaleString()}</div>
    <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{title}</div>
  </div>
);

export default ShareDialog;

